begin;
create extension if not exists pgcrypto;
create or replace function public.angelcare_marketplace_operations_reference(prefix text) returns text language sql volatile as $$select upper(prefix)||'-'||to_char(now(),'YYMMDD')||'-'||upper(substr(encode(gen_random_bytes(5),'hex'),1,8))$$;
create table if not exists public.angelcare_marketplace_fulfillment_cases(
 id uuid primary key default gen_random_uuid(),public_reference text unique not null default public.angelcare_marketplace_operations_reference('FUL'),journey_id uuid,conversion_session_id uuid,canonical_object_type text not null,canonical_object_id uuid,
 fulfillment_kind text not null check(fulfillment_kind in('product_order','kit_order','family_service','recurring_service','academy_delivery','b2b_programme','partner_activation','quality_assessment')),
 title text not null,status text not null default 'commercially_confirmed' check(status in('commercially_confirmed','readiness_review','awaiting_acceptance','accepted','allocation_required','allocated','preparing','in_execution','evidence_required','quality_review','customer_acceptance','reconciliation_required','reconciled','closed','blocked','cancelled')),
 priority text not null default 'normal',risk_level text not null default 'low' check(risk_level in('low','medium','high','critical')),tenant_id uuid,territory_id uuid,customer_id uuid,organization_id uuid,vendor_id uuid,provider_id uuid,
 scheduled_start_at timestamptz,scheduled_end_at timestamptz,due_at timestamptz,next_action text,readiness_snapshot jsonb not null default '{}',commercial_snapshot jsonb not null default '{}',customer_visibility jsonb not null default '{}',created_by uuid,updated_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),closed_at timestamptz,
 unique nulls not distinct(journey_id,canonical_object_type,canonical_object_id));
create table if not exists public.angelcare_marketplace_fulfillment_obligations(id uuid primary key default gen_random_uuid(),fulfillment_case_id uuid not null references public.angelcare_marketplace_fulfillment_cases(id) on delete cascade,obligation_key text not null,title text not null,responsible_type text not null check(responsible_type in('vendor','provider','angelcare','customer','organization')),responsible_id uuid,status text not null default 'pending',due_at timestamptz,completed_at timestamptz,blocker_reason text,customer_visible boolean not null default false,financial_consequence jsonb not null default '{}',evidence_requirements jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(fulfillment_case_id,obligation_key));
create table if not exists public.angelcare_marketplace_fulfillment_events(id uuid primary key default gen_random_uuid(),fulfillment_case_id uuid not null references public.angelcare_marketplace_fulfillment_cases(id) on delete cascade,event_type text not null,title text not null,event_data jsonb not null default '{}',authority_type text not null,authority_object_id uuid,customer_visible boolean not null default false,occurred_at timestamptz not null default now(),created_by uuid);
create table if not exists public.angelcare_marketplace_fulfillment_evidence(id uuid primary key default gen_random_uuid(),fulfillment_case_id uuid not null references public.angelcare_marketplace_fulfillment_cases(id) on delete cascade,evidence_type text not null,authority_type text not null,authority_object_id uuid,title text not null,storage_reference text,evidence_data jsonb not null default '{}',validation_status text not null default 'submitted' check(validation_status in('submitted','under_review','validated','rejected','superseded')),customer_visible boolean not null default false,submitted_by uuid,submitted_at timestamptz not null default now(),validated_by uuid,validated_at timestamptz);
create table if not exists public.angelcare_marketplace_vendor_links(id uuid primary key default gen_random_uuid(),organization_id uuid not null,vendor_reference text unique not null,display_name text not null,status text not null default 'onboarding',tenant_id uuid,territory_id uuid,territory_ids uuid[] not null default '{}',catalog_item_ids uuid[] not null default '{}',contract_reference text,service_level jsonb not null default '{}',readiness jsonb not null default '{}',performance jsonb not null default '{}',settlement_status text not null default 'not_ready',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_provider_links(id uuid primary key default gen_random_uuid(),provider_id uuid unique not null,display_name text not null,status text not null default 'linked',tenant_id uuid,territory_id uuid,territory_ids uuid[] not null default '{}',approved_service_types text[] not null default '{}',eligibility_snapshot jsonb not null default '{}',academy_snapshot jsonb not null default '{}',trust_snapshot jsonb not null default '{}',payable_status text not null default 'not_ready',performance jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_return_cases(id uuid primary key default gen_random_uuid(),public_reference text unique not null default public.angelcare_marketplace_operations_reference('RET'),fulfillment_case_id uuid not null references public.angelcare_marketplace_fulfillment_cases(id),return_type text not null,reason text not null,status text not null default 'submitted',eligibility_status text not null default 'review_required',remedy_type text,finance_handover_status text not null default 'not_required',tenant_id uuid,territory_id uuid,requested_by uuid,requested_at timestamptz not null default now(),resolved_at timestamptz,open_flag boolean generated always as(status not in('resolved','closed','rejected')) stored);
create table if not exists public.angelcare_marketplace_replacement_cases(id uuid primary key default gen_random_uuid(),public_reference text unique not null default public.angelcare_marketplace_operations_reference('RPL'),fulfillment_case_id uuid not null references public.angelcare_marketplace_fulfillment_cases(id),replacement_type text not null,reason text not null,status text not null default 'requested',replacement_authority_type text,replacement_authority_id uuid,tenant_id uuid,territory_id uuid,promised_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_disputes(id uuid primary key default gen_random_uuid(),public_reference text unique not null default public.angelcare_marketplace_operations_reference('DSP'),fulfillment_case_id uuid references public.angelcare_marketplace_fulfillment_cases(id),journey_id uuid,dispute_type text not null,claimant_type text not null,claimant_id uuid,counterparty_type text not null,counterparty_id uuid,status text not null default 'open' check(status in('open','triage','investigation','decision_pending','remedy_pending','resolved','closed','reopened')),risk_level text not null default 'medium' check(risk_level in('low','medium','high','critical')),financial_exposure numeric(18,2) not null default 0,currency text not null default 'MAD',summary text not null,investigation_summary text,decision text,remedy_type text,owner_id uuid,tenant_id uuid,territory_id uuid,sla_due_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),closed_at timestamptz,open_flag boolean generated always as(status not in('resolved','closed')) stored);
create table if not exists public.angelcare_marketplace_dispute_evidence(id uuid primary key default gen_random_uuid(),dispute_id uuid not null references public.angelcare_marketplace_disputes(id) on delete cascade,evidence_type text not null,title text not null,authority_type text not null,authority_object_id uuid,evidence_data jsonb not null default '{}',storage_reference text,visibility text not null default 'internal',submitted_by uuid,submitted_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_recovery_plans(id uuid primary key default gen_random_uuid(),public_reference text unique not null default public.angelcare_marketplace_operations_reference('RCV'),fulfillment_case_id uuid references public.angelcare_marketplace_fulfillment_cases(id),dispute_id uuid references public.angelcare_marketplace_disputes(id),journey_id uuid,recovery_type text not null,status text not null default 'draft',urgency text not null default 'medium',customer_summary text not null,internal_strategy text not null,approved_remedy jsonb not null default '{}',owner_id uuid,tenant_id uuid,territory_id uuid,due_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),open_flag boolean generated always as(status not in('completed','cancelled','closed')) stored);
create table if not exists public.angelcare_marketplace_recovery_actions(id uuid primary key default gen_random_uuid(),recovery_plan_id uuid not null references public.angelcare_marketplace_recovery_plans(id) on delete cascade,action_type text not null,title text not null,status text not null default 'pending',responsible_type text not null,responsible_id uuid,due_at timestamptz,completed_at timestamptz,evidence jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_reconciliation_cases(id uuid primary key default gen_random_uuid(),public_reference text unique not null default public.angelcare_marketplace_operations_reference('REC'),fulfillment_case_id uuid references public.angelcare_marketplace_fulfillment_cases(id),journey_id uuid,status text not null default 'draft' check(status in('draft','evidence_incomplete','review','approval_pending','approved','finance_handover','posted','disputed','closed')),contracted_amount numeric(18,2) not null default 0,adjustment_amount numeric(18,2) not null default 0,final_reconciled_amount numeric(18,2) not null default 0,currency text not null default 'MAD',finance_handover_status text not null default 'not_submitted',finance_authority_id uuid,evidence_complete boolean not null default false,dispute_open boolean not null default false,owner_id uuid,tenant_id uuid,territory_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),closed_at timestamptz);
create table if not exists public.angelcare_marketplace_reconciliation_lines(id uuid primary key default gen_random_uuid(),reconciliation_case_id uuid not null references public.angelcare_marketplace_reconciliation_cases(id) on delete cascade,line_type text not null,label text not null,amount numeric(18,2) not null,currency text not null default 'MAD',direction text not null check(direction in('debit','credit')),authority_type text not null,authority_object_id uuid,approval_status text not null default 'pending',evidence jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_settlement_readiness(id uuid primary key default gen_random_uuid(),fulfillment_case_id uuid not null references public.angelcare_marketplace_fulfillment_cases(id),counterparty_type text not null check(counterparty_type in('vendor','provider')),counterparty_id uuid not null,status text not null default 'blocked',evidence_complete boolean not null default false,quality_validated boolean not null default false,customer_accepted boolean not null default false,incident_clear boolean not null default false,dispute_clear boolean not null default false,amount_validated boolean not null default false,document_ready boolean not null default false,approval_ready boolean not null default false,blocked_reasons text[] not null default '{}',amount numeric(18,2) not null default 0,currency text not null default 'MAD',tenant_id uuid,territory_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),ready_flag boolean generated always as(evidence_complete and quality_validated and customer_accepted and incident_clear and dispute_clear and amount_validated and document_ready and approval_ready) stored,unique(fulfillment_case_id,counterparty_type,counterparty_id));
create table if not exists public.angelcare_marketplace_operational_exceptions(id uuid primary key default gen_random_uuid(),public_reference text unique not null default public.angelcare_marketplace_operations_reference('EXC'),fulfillment_case_id uuid references public.angelcare_marketplace_fulfillment_cases(id),exception_type text not null,status text not null default 'open',risk_level text not null default 'medium',customer_harm_level text not null default 'none',financial_exposure numeric(18,2) not null default 0,sla_exposure_minutes integer not null default 0,summary text not null,next_action text not null,owner_id uuid,tenant_id uuid,territory_id uuid,due_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operational_sla_events(id uuid primary key default gen_random_uuid(),fulfillment_case_id uuid references public.angelcare_marketplace_fulfillment_cases(id),exception_id uuid references public.angelcare_marketplace_operational_exceptions(id),sla_key text not null,target_at timestamptz not null,achieved_at timestamptz,breached boolean not null default false,breach_minutes integer not null default 0,evidence jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_operations_policies(id uuid primary key default gen_random_uuid(),policy_key text not null,scope_type text not null default 'global',territory_id uuid,tenant_id uuid,policy_value jsonb not null default '{}',active boolean not null default true,version integer not null default 1,approved_by uuid,approved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique nulls not distinct(policy_key,scope_type,territory_id,tenant_id,version));
create index if not exists angelcare_marketplace_fulfillment_cases_command_idx on public.angelcare_marketplace_fulfillment_cases(status,risk_level,due_at);
create index if not exists angelcare_marketplace_disputes_command_idx on public.angelcare_marketplace_disputes(status,risk_level,sla_due_at);
create index if not exists angelcare_marketplace_reconciliation_command_idx on public.angelcare_marketplace_reconciliation_cases(status,finance_handover_status);
create or replace view public.angelcare_marketplace_operations_command_v with(security_invoker=true) as select f.*,(select count(*) from public.angelcare_marketplace_fulfillment_obligations o where o.fulfillment_case_id=f.id and o.status not in('completed','waived')) open_obligations,(select count(*) from public.angelcare_marketplace_fulfillment_evidence e where e.fulfillment_case_id=f.id and e.validation_status='validated') validated_evidence,(f.due_at is not null and f.due_at<now() and f.status not in('closed','cancelled')) late_flag from public.angelcare_marketplace_fulfillment_cases f;
create or replace view public.angelcare_marketplace_operations_financial_v with(security_invoker=true) as select r.*,coalesce((select sum(case when l.direction='credit' then -l.amount else l.amount end) from public.angelcare_marketplace_reconciliation_lines l where l.reconciliation_case_id=r.id),0) calculated_adjustment from public.angelcare_marketplace_reconciliation_cases r;
create or replace function public.angelcare_marketplace_materialize_fulfillment_from_journey() returns trigger language plpgsql security definer set search_path=public as $$begin if new.status in('qualified','scheduled','in_preparation','in_progress') then insert into public.angelcare_marketplace_fulfillment_cases(journey_id,canonical_object_type,canonical_object_id,fulfillment_kind,title,status,priority,risk_level,tenant_id,territory_id,customer_id,organization_id,scheduled_start_at,scheduled_end_at,due_at,next_action,commercial_snapshot,customer_visibility) values(new.id,new.canonical_object_type,new.canonical_object_id,case new.journey_type when 'product_order' then 'product_order' when 'kit_order' then 'kit_order' when 'academy_enrollment' then 'academy_delivery' when 'b2b_quotation' then 'b2b_programme' when 'partner_activation' then 'partner_activation' when 'quality_assessment' then 'quality_assessment' when 'recurring_service' then 'recurring_service' else 'family_service' end,new.title,'commercially_confirmed','normal',new.risk_level,new.tenant_id,new.territory_id,new.owner_user_id,new.crm_account_id,new.scheduled_start_at,new.scheduled_end_at,new.next_action_due_at,new.next_action_label,jsonb_build_object('journey_reference',new.public_reference,'financial_status',new.financial_status),jsonb_build_object('journey_status',new.status)) on conflict(journey_id,canonical_object_type,canonical_object_id) do nothing;end if;return new;end$$;
drop trigger if exists angelcare_marketplace_journey_to_fulfillment on public.angelcare_marketplace_journeys;
create trigger angelcare_marketplace_journey_to_fulfillment after insert or update of status on public.angelcare_marketplace_journeys for each row execute function public.angelcare_marketplace_materialize_fulfillment_from_journey();
insert into public.angelcare_marketplace_fulfillment_cases(journey_id,canonical_object_type,canonical_object_id,fulfillment_kind,title,status,priority,risk_level,tenant_id,territory_id,customer_id,organization_id,scheduled_start_at,scheduled_end_at,due_at,next_action,commercial_snapshot,customer_visibility) select j.id,j.canonical_object_type,j.canonical_object_id,case j.journey_type when 'product_order' then 'product_order' when 'kit_order' then 'kit_order' when 'academy_enrollment' then 'academy_delivery' when 'b2b_quotation' then 'b2b_programme' when 'partner_activation' then 'partner_activation' when 'quality_assessment' then 'quality_assessment' when 'recurring_service' then 'recurring_service' else 'family_service' end,j.title,'commercially_confirmed','normal',j.risk_level,j.tenant_id,j.territory_id,j.owner_user_id,j.crm_account_id,j.scheduled_start_at,j.scheduled_end_at,j.next_action_due_at,j.next_action_label,jsonb_build_object('journey_reference',j.public_reference,'financial_status',j.financial_status),jsonb_build_object('journey_status',j.status) from public.angelcare_marketplace_journeys j where j.status in('qualified','scheduled','in_preparation','in_progress') on conflict(journey_id,canonical_object_type,canonical_object_id) do nothing;
insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values('marketplace.operations.commerce.view','Voir Marketplace Operations','Operations & Reconciliation',false),('marketplace.operations.commerce.manage','Gérer Marketplace Operations','Operations & Reconciliation',true),('marketplace.operations.evidence.manage','Gérer les preuves','Operations & Reconciliation',true),('marketplace.operations.returns.manage','Gérer retours','Operations & Reconciliation',true),('marketplace.operations.disputes.manage','Gérer litiges','Operations & Reconciliation',true),('marketplace.operations.recovery.manage','Gérer recovery','Operations & Reconciliation',true),('marketplace.operations.reconciliation.approve','Approuver réconciliation','Operations & Reconciliation',true),('marketplace.vendors.commerce.manage','Gérer Vendor Commerce','Operations & Reconciliation',true),('marketplace.providers.commerce.manage','Gérer Provider Commerce','Operations & Reconciliation',true) on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive') and(p.permission_key like 'marketplace.operations.%' or p.permission_key like 'marketplace.vendors.%' or p.permission_key like 'marketplace.providers.commerce.%') on conflict do nothing;
alter table public.angelcare_marketplace_modules drop constraint if exists angelcare_marketplace_modules_introduced_by_mega_zip_check;
alter table public.angelcare_marketplace_modules add constraint angelcare_marketplace_modules_introduced_by_mega_zip_check check(introduced_by_mega_zip>=1);
insert into public.angelcare_marketplace_modules(module_key,name,description,route_prefix,module_type,audience,status,enabled,required_permissions,required_dependencies,territory_aware,tenant_aware,locale_aware,health_status,owner_role,introduced_by_mega_zip) values('operations-reconciliation-universe','Marketplace Operations & Reconciliation','Fulfillment, counterparties, returns, disputes, recovery, settlements and Finance handover.','/angelcare-marketplace/admin/operations','operating_engine',array['admin','executive','operations','finance']::text[],'enabled',true,array['marketplace.operations.view']::text[],array['journey-control-universe','conversion-universe','finance-authority','provider-workforce','operations-execution']::text[],true,true,true,'healthy','marketplace_operations_reconciliation_manager',24) on conflict(module_key) do update set name=excluded.name,description=excluded.description,route_prefix=excluded.route_prefix,status='enabled',enabled=true,required_permissions=excluded.required_permissions,required_dependencies=excluded.required_dependencies,health_status='healthy',updated_at=now();
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.operations.reconciliation.enabled','Marketplace Operations & Reconciliation','Fulfillment, accountability, recovery and Finance handover.',true,'active','Global Marketplace Delivery 5') on conflict(flag_key) do update set enabled=true,status='active',reason=excluded.reason,updated_at=now();
alter table public.angelcare_marketplace_fulfillment_cases enable row level security;
alter table public.angelcare_marketplace_fulfillment_obligations enable row level security;
alter table public.angelcare_marketplace_fulfillment_events enable row level security;
alter table public.angelcare_marketplace_fulfillment_evidence enable row level security;
alter table public.angelcare_marketplace_vendor_links enable row level security;
alter table public.angelcare_marketplace_provider_links enable row level security;
alter table public.angelcare_marketplace_return_cases enable row level security;
alter table public.angelcare_marketplace_replacement_cases enable row level security;
alter table public.angelcare_marketplace_disputes enable row level security;
alter table public.angelcare_marketplace_dispute_evidence enable row level security;
alter table public.angelcare_marketplace_recovery_plans enable row level security;
alter table public.angelcare_marketplace_recovery_actions enable row level security;
alter table public.angelcare_marketplace_reconciliation_cases enable row level security;
alter table public.angelcare_marketplace_reconciliation_lines enable row level security;
alter table public.angelcare_marketplace_settlement_readiness enable row level security;
alter table public.angelcare_marketplace_operational_exceptions enable row level security;
alter table public.angelcare_marketplace_operational_sla_events enable row level security;
alter table public.angelcare_marketplace_operations_policies enable row level security;
revoke all on table public.angelcare_marketplace_fulfillment_cases,public.angelcare_marketplace_fulfillment_obligations,public.angelcare_marketplace_fulfillment_events,public.angelcare_marketplace_fulfillment_evidence,public.angelcare_marketplace_vendor_links,public.angelcare_marketplace_provider_links,public.angelcare_marketplace_return_cases,public.angelcare_marketplace_replacement_cases,public.angelcare_marketplace_disputes,public.angelcare_marketplace_dispute_evidence,public.angelcare_marketplace_recovery_plans,public.angelcare_marketplace_recovery_actions,public.angelcare_marketplace_reconciliation_cases,public.angelcare_marketplace_reconciliation_lines,public.angelcare_marketplace_settlement_readiness,public.angelcare_marketplace_operational_exceptions,public.angelcare_marketplace_operational_sla_events,public.angelcare_marketplace_operations_policies from anon,authenticated;
grant all on table public.angelcare_marketplace_fulfillment_cases,public.angelcare_marketplace_fulfillment_obligations,public.angelcare_marketplace_fulfillment_events,public.angelcare_marketplace_fulfillment_evidence,public.angelcare_marketplace_vendor_links,public.angelcare_marketplace_provider_links,public.angelcare_marketplace_return_cases,public.angelcare_marketplace_replacement_cases,public.angelcare_marketplace_disputes,public.angelcare_marketplace_dispute_evidence,public.angelcare_marketplace_recovery_plans,public.angelcare_marketplace_recovery_actions,public.angelcare_marketplace_reconciliation_cases,public.angelcare_marketplace_reconciliation_lines,public.angelcare_marketplace_settlement_readiness,public.angelcare_marketplace_operational_exceptions,public.angelcare_marketplace_operational_sla_events,public.angelcare_marketplace_operations_policies to service_role;
grant select on table public.angelcare_marketplace_operations_command_v,public.angelcare_marketplace_operations_financial_v to service_role;
commit;
